var EXTRA=[{"dot": "gray", "j": "J Robot Surg", "h": "Perni del tracker nella protesi robotica: complicanze rare, per lo più ferite ai siti tibiali fuori dall'incisione", "v": "Revisione sistematica con meta-analisi di studi di livello basso: i perni dentro e fuori l'incisione non mostrano una differenza significativa. È un dato di sicurezza di procedura, senza esiti funzionali.", "pmid": "42989037", "doi": "10.1007/s11701-026-04134-6", "temi": ["protesi robotica", "perni del tracker", "complicanze"]}, {"dot": "gray", "j": "KSSTA", "h": "Allotrapianto di menisco: l'estrusione all'ecografia, a lungo termine, non correla con funzione né con segni radiografici", "v": "Coorte con controllo a molti anni: l'estrusione è maggiore nel trapianto mediale e maggiore dell'altro lato, ma non va usata come sostituto degli esiti clinici. Tocca la questione dell'estrusione nel menisco.", "pmid": "42994403", "doi": "10.1002/ksa.70674", "temi": ["menisco", "allotrapianto", "estrusione"]}, {"dot": "gray", "j": "Am J Sports Med", "h": "Pie-crusting del collaterale mediale vicino alla linea articolare: più estrusione meniscale rispetto alla sede prossimale", "v": "Studio di laboratorio su ginocchia di cadavere, pochi esemplari: dà un indizio meccanico sul punto da scegliere, senza esiti clinici.", "pmid": "42989880", "doi": "10.1177/03635465261485706", "temi": ["collaterale mediale", "artroscopia", "biomeccanica"]}, {"dot": "gray", "j": "KSSTA", "h": "Iperestensione preoperatoria nella protesi robotica con crociato conservato: tagli ossei minori senza un abbassamento rilevante della linea articolare", "v": "Coorte retrospettiva di un solo chirurgo: i punteggi funzionali a un anno non differiscono fra i gruppi. Descrive come adattare i tagli, non dimostra una strategia migliore.", "pmid": "42994402", "doi": "10.1002/ksa.70680", "temi": ["protesi robotica", "iperestensione", "linea articolare"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Protesi robotica con allineamento cinematico restrittivo: un gap laterale più piccolo del mediale in flessione profonda si associa a minor soddisfazione", "v": "Studio retrospettivo monocentrico: suggerisce di guidare la rotazione femorale con la simulazione dei gap, ma l'associazione non prova che modificarla migliori il risultato.", "pmid": "42988280", "doi": "10.1016/j.arth.2026.10.048", "temi": ["protesi robotica", "gap", "allineamento cinematico"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Accesso subvastus contro parapatellare mediale: vantaggio costante solo su degenza e sollevamento della gamba", "v": "Meta-analisi con valutazione GRADE: la maggior parte delle differenze su dolore e perdita di sangue perde significatività nei soli RCT.", "pmid": "42994651", "doi": "10.1016/j.arth.2026.11.020", "temi": ["protesi totale", "accesso chirurgico", "meta-analisi"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Manicotti metafisari nelle revisioni di protesi di ginocchio: osteointegrazione quasi completa, l'infezione è la prima causa di fallimento", "v": "Meta-analisi di serie senza gruppo di confronto: descrive la tenuta dell'impianto, non lo confronta con un'altra strategia.", "pmid": "42994645", "doi": "10.1016/j.arth.2026.11.003", "temi": ["revisione protesica", "manicotti metafisari", "difetti ossei"]}, {"dot": "gray", "j": "Knee Surg Relat Res", "h": "Modello predittivo di pianificazione nella protesi robotica: i gap pianificati restano vicini al bersaglio nel software", "v": "Concordanza calcolata nel software: i gap bersaglio sono impostazioni del programma e non misure intraoperatorie né esiti clinici.", "pmid": "42989400", "doi": "10.1186/s43019-026-00357-x", "temi": ["protesi robotica", "pianificazione", "apprendimento automatico"]}, {"dot": "gray", "j": "KSSTA", "h": "Menisco laterale ipermobile: un punteggio clinico e di risonanza per riconoscerlo prima dell'artroscopia", "v": "Modello retrospettivo con validazione interna per ricampionamento: manca la validazione esterna su altri centri.", "pmid": "42994404", "doi": "10.1002/ksa.70681", "temi": ["menisco laterale", "diagnosi", "punteggio predittivo"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Allotrapianto osteocondrale: sesso femminile, diagnosi primaria e funzione preoperatoria più alta si associano al mancato miglioramento rilevante", "v": "Coorte retrospettiva di registro monochirurgo con follow-up molto lungo: associazioni, non cause; utile per il colloquio sulle aspettative.", "pmid": "42989614", "doi": "10.1002/arj.70613", "temi": ["cartilagine", "allotrapianto osteocondrale", "fattori prognostici"]}, {"dot": "gray", "j": "Bone Joint Open", "h": "Artrometro automatico dopo la protesi totale: la stabilità sagittale oggettiva si lega ai punteggi riferiti solo in parte", "v": "Coorte prospettica a doppio cieco con due disegni d'impianto: la misura oggettiva distingue gli impianti, ma l'abstract non dice che cosa fare di questa differenza.", "pmid": "42987924", "doi": "10.1302/2633-1462.711.BJO-2026-0095.R1", "temi": ["protesi totale", "stabilità sagittale", "artrometria"]}, {"dot": "gray", "j": "Arch Orthop Trauma Surg", "h": "Trocleoplastica con ricostruzione del MPFL: l'indice di Caton-Deschamps alla risonanza si riduce nel medio-lungo termine", "v": "Serie retrospettiva molto piccola; gli autori stessi scrivono che non si può dire se rifletta una vera distalizzazione della rotula.", "pmid": "42993318", "doi": "10.1007/s00402-026-06542-7", "temi": ["MPFL", "trocleoplastica", "altezza rotulea"]}];

var SCOPERTE=[{"t": "Intelligenza artificiale e robot nella protesi di ginocchio non sono la stessa cosa: una mappa di che cosa è dimostrato per ciascuna funzione", "v": "Una revisione narrativa separa l'esecuzione robotica, la navigazione e le previsioni algoritmiche: la precisione di posizionamento ha l'evidenza più matura, mentre per le previsioni mancano dimostrazioni cliniche dirette. Utile per distinguere ciò che promette un fornitore da ciò che è provato.", "pmid": "42989357", "doi": "10.1186/s42836-026-00444-0", "temi": ["intelligenza artificiale", "protesi robotica", "evidenza"]}, {"t": "Genetica della rottura del crociato nelle donne: dopo diciannove studi, nessuno studio sull'intero genoma", "v": "Una revisione sistematica trova soprattutto piccoli studi caso-controllo, con campioni che in parte si sovrappongono e un segnale principale che non regge nello studio prospettico. Un campo adiacente dove il dato più utile è l'assenza di dati.", "pmid": "42990781", "doi": "10.1136/bmjsem-2026-003274", "temi": ["LCA", "genetica", "sesso femminile"]}, {"t": "Allineamento nel piano coronale e stress sulla cartilagine dopo LCA in adolescenza: un modello a elementi finiti su cinque ragazzi", "v": "Ingegneria applicata a un tuo ambito (LCA in adolescenza): l'allineamento cambia lo stress sulla cartilagine di ciascun ragazzo ma non la cinematica. Un pilota esplorativo, senza esiti clinici.", "pmid": "42992944", "doi": "10.1080/10255842.2026.2758691", "temi": ["LCA adolescente", "elementi finiti", "allineamento"]}];

var SOC={"1": {"video": "Quando si ripara la radice del menisco, il menisco può restare spostato verso l'esterno dell'articolazione. Un gruppo di ventidue esperti internazionali ha scritto quando vale la pena aggiungere alla sutura un punto che lo tiene al suo posto: la centralizzazione.\n\nLo suggeriscono quando alla risonanza la sporgenza supera i 3 millimetri; lo sconsigliano se l'artrosi è avanzata; lo sostengono insieme a un'osteotomia della tibia nelle gambe a O con sporgenza del menisco interno. Nessun tipo di fissazione è stato preferito.\n\nIl limite: è un parere di esperti e non il risultato di uno studio sui pazienti. Le revisioni dei dati clinici fatte finora non hanno mostrato un vantaggio chiaro.\nFonte: PubMed, PMID 42989778.", "linkedin": "Centralizzazione del menisco con lesione di radice o trapianto: consensus Delphi di 22 esperti internazionali (Arthroscopy, 2026), 35 affermazioni su 39 mantenute.\n\nDa considerare con riparazione della radice e trapianto per ridurre l'estrusione; soglia alla RM oltre 3 mm nella radice posteriore mediale, e nella laterale con lesione del legamento menisco-femorale; sconsigliata nell'artrosi avanzata; sostenuta con osteotomia tibiale alta nel varo. Transtibiale, ancore e ibridi accettabili.\n\nIl limite: livello V; percentuali di accordo per affermazione non riportate; soglia non validata contro la sola sutura.\nFonte: PubMed, PMID 42989778.", "instagram": "Menisco con lesione della radice: quando valutare un rinforzo in più.\n\nEsperti internazionali: da considerare se il menisco sporge oltre 3 millimetri alla risonanza.\n\nParere di esperti, non uno studio. PMID 42989778.", "pazienti": "Quando si ripara la radice del menisco, il menisco può restare un po' spostato verso l'esterno. Un gruppo di esperti di diversi paesi ha scritto che, se lo spostamento supera i 3 millimetri alla risonanza, si può valutare un punto in più per tenerlo al suo posto.\n\nNon lo suggeriscono se l'artrosi è già avanzata. Non indicano un solo modo di fissare la sutura: dipende dal caso e dal chirurgo.\n\nIl limite: è un parere di esperti, non l'esito di uno studio sui pazienti, e non un obbligo. La scelta va discussa con il proprio chirurgo.\nFonte: PubMed, PMID 42989778."}};

var SOCV={"1": {"video": {"chir": ["Consensus Delphi su centralizzazione del menisco con lesione di radice o trapianto (Arthroscopy, 2026). Ventidue esperti internazionali, tre round, trentacinque affermazioni mantenute su trentanove, con soglia di accordo almeno 75% e disaccordo sotto 20%.", "Il pannello considera la centralizzazione con la riparazione della radice e con il trapianto per ridurre l'estrusione e migliorare la meccanica di contatto. Soglia: estrusione alla RM oltre 3 mm nella radice posteriore mediale; per la laterale serve anche la lesione del legamento menisco-femorale. Sconsigliata nell'artrosi avanzata, sostenuta con l'osteotomia tibiale alta nel varo. Transtibiale, ancore e costrutti ibridi sono tutti accettabili.", "Il limite: livello V, opinione di esperti. Percentuali di accordo per affermazione non riportate; la soglia di 3 mm non è validata contro la sola sutura. «Può essere considerata» non è un'indicazione.\nFonte: PubMed, PMID 42989778."], "misto": ["Quando si ripara la radice del menisco, il menisco può restare spostato verso l'esterno dell'articolazione. Un gruppo di ventidue esperti internazionali ha scritto quando vale la pena aggiungere alla sutura un punto che lo tiene al suo posto: la centralizzazione.", "Lo suggeriscono quando alla risonanza la sporgenza supera i 3 millimetri; lo sconsigliano se l'artrosi è avanzata; lo sostengono insieme a un'osteotomia della tibia nelle gambe a O con sporgenza del menisco interno. Nessun tipo di fissazione è stato preferito: vanno bene tunnel nella tibia, ancore o una combinazione.", "Il limite: è un parere di esperti e non il risultato di uno studio sui pazienti. Le revisioni dei dati clinici fatte finora non hanno mostrato un vantaggio chiaro.\nFonte: PubMed, PMID 42989778."], "pazienti": ["Quando si ripara la radice del menisco, il menisco può restare un po' spostato verso l'esterno. Un gruppo di esperti di diversi paesi ha scritto che, se lo spostamento supera i 3 millimetri alla risonanza, si può valutare un punto in più per tenerlo al suo posto.", "Non lo suggeriscono se l'artrosi è già avanzata. Non indicano un solo modo di fissare la sutura: dipende dal caso e dal chirurgo.", "Il limite: è un parere di esperti, non l'esito di uno studio sui pazienti, e non un obbligo. La scelta va discussa con il proprio chirurgo.\nFonte: PubMed, PMID 42989778."]}, "linkedin": {"chir": ["Centralizzazione del menisco con lesione di radice o trapianto: consensus Delphi di 22 esperti internazionali (Arthroscopy, 2026), 35 affermazioni su 39 mantenute.", "Da considerare con riparazione della radice e trapianto per ridurre l'estrusione; soglia alla RM oltre 3 mm nella radice posteriore mediale, e nella laterale con lesione del legamento menisco-femorale; sconsigliata nell'artrosi avanzata; sostenuta con osteotomia tibiale alta nel varo. Transtibiale, ancore e ibridi accettabili.", "Il limite: livello V; percentuali di accordo per affermazione non riportate; soglia non validata contro la sola sutura.\nFonte: PubMed, PMID 42989778."], "misto": ["Lesione della radice del menisco: ventidue esperti internazionali indicano quando valutare un rinforzo in più della sutura (Arthroscopy, 2026).", "Lo suggeriscono se alla risonanza il menisco sporge più di 3 millimetri, non in presenza di artrosi avanzata, e insieme a un'osteotomia tibiale nel varo con menisco sporgente. Nessun metodo di fissazione è stato preferito.", "Il limite: è un parere di esperti, non uno studio sui pazienti.\nFonte: PubMed, PMID 42989778."], "pazienti": ["Lesione della radice del menisco: cosa dicono gli esperti sul rinforzo della sutura.", "Un gruppo di esperti suggerisce di valutare un punto in più quando il menisco sporge più di 3 millimetri alla risonanza, non quando l'artrosi è avanzata.", "È un parere di esperti e non un obbligo: la scelta dipende dal caso.\nFonte: PubMed, PMID 42989778."]}, "instagram": {"chir": ["Centralizzazione del menisco: consensus Delphi di 22 esperti.", "Da considerare con estrusione alla RM oltre 3 mm; sconsigliata nell'artrosi avanzata; fissazione non vincolata.", "Livello V, soglia non validata. PMID 42989778."], "misto": ["Menisco con lesione della radice: quando valutare un rinforzo in più.", "Esperti internazionali: da considerare se il menisco sporge oltre 3 millimetri alla risonanza.", "Parere di esperti, non uno studio. PMID 42989778."], "pazienti": ["Menisco e sutura della radice: cosa dicono gli esperti.", "Se il menisco sporge più di 3 millimetri alla risonanza si può valutare un punto in più.", "È un parere, non un obbligo. PMID 42989778."]}, "reel": {"chir": ["[Centralizzazione del menisco]", "Consensus: da considerare con estrusione alla RM oltre 3 mm.", "Livello V. PMID 42989778."], "misto": ["[Menisco e radice]", "Esperti: un rinforzo in più se il menisco sporge oltre 3 millimetri.", "Parere di esperti. PMID 42989778."], "pazienti": ["[Menisco e sutura]", "Se il menisco sporge troppo, si può valutare un punto in più.", "Parere, non obbligo. PMID 42989778."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #risonanzamagnetica #artroscopia #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino", "kw": "menisco, lesione della radice del menisco, sutura del menisco, risonanza magnetica ginocchio, chirurgia artroscopica, ginocchio operato"}};

var NLB={"1": {"prof": ["Centralizzazione del menisco con lesione di radice: consensus Delphi su soglie, indicazioni e fissazione", "Consensus di esperti (Arthroscopy, 2026; livello V, solo abstract): 22 esperti, tre round, 35 affermazioni su 39 mantenute. Centralizzazione da considerare con riparazione della radice e trapianto di menisco; con estrusione alla RM oltre 3 mm nella radice posteriore mediale; sconsigliata nell'artrosi avanzata; sostenuta con osteotomia tibiale alta nel varo. Transtibiale, ancore e costrutti ibridi accettabili.", "Nota critica: opinione di esperti, non prova; percentuali di accordo per affermazione non riportate; la soglia di 3 mm non è validata contro la sola sutura."], "mix": ["Menisco con lesione della radice: esperti internazionali indicano quando valutare un rinforzo in più", "Un gruppo di 22 esperti internazionali ha messo per iscritto quando, nelle lesioni della radice del menisco e nei trapianti di menisco, vale la pena aggiungere alla sutura un punto che tiene il menisco al suo posto (la centralizzazione). Lo suggeriscono quando alla risonanza il menisco sporge dall'articolazione di più di 3 millimetri; lo sconsigliano se l'artrosi è avanzata.", "Nota sul limite: è un parere di esperti e non il risultato di uno studio sui pazienti; i dati clinici disponibili finora non hanno mostrato un vantaggio chiaro."], "paz": ["Lesione della radice del menisco: cosa dicono gli esperti sul rinforzo della sutura", "Quando si ripara la radice del menisco, il menisco può sporgere in fuori dall'articolazione. Un gruppo di esperti ha scritto che, se la sporgenza supera i 3 millimetri alla risonanza, si può valutare un punto in più per tenerlo al suo posto. Non vale quando l'artrosi è già avanzata.", "Nota rassicurante: è un parere di esperti e non un obbligo; la scelta dipende dal singolo caso e dal parere del proprio chirurgo."], "kw": "menisco, radice del menisco, sutura del menisco, risonanza magnetica ginocchio, chirurgia artroscopica"}, "2": {"prof": ["Allineamento in protesi totale: funzionale e cinematico migliorano il Forgotten Joint Score, certezza bassa", "Meta-analisi di rete (J Arthroplasty, 2026; 61 studi, 22 RCT, 7.822 pazienti; solo abstract): rispetto al meccanico, Forgotten Joint Score +14,24 con funzionale (IC 95% 3,32-25,16), +12,28 con cinematico non restrittivo (IC 95% 9,06-15,51), +8,75 con restrittivo (IC 95% 3,41-14,08). Solo il funzionale supera la soglia minima rilevante. Certezza GRADE bassa o molto bassa.", "Nota critica: due terzi degli studi osservazionali, vantaggio minore negli RCT, eterogeneità alta, confronti diretti scarsi; sistema robotico non specificato."], "mix": ["Protesi totale di ginocchio: gli allineamenti personalizzati sembrano dare più sensazione di naturalezza, ma le prove sono deboli", "Una sintesi di 61 studi su quasi ottomila pazienti confronta il modo di posizionare la protesi. Con le strategie personalizzate i pazienti riferiscono un ginocchio che si fa dimenticare di più rispetto al metodo tradizionale; solo una delle strategie supera la differenza ritenuta chiaramente percepibile.", "Nota sul limite: gli studi sono per lo più osservazionali, il vantaggio si riduce negli studi randomizzati e la certezza complessiva è bassa o molto bassa."], "paz": ["Protesi di ginocchio: come viene posizionata può cambiare quanto la si sente", "Una sintesi di 61 studi su quasi ottomila pazienti ha confrontato diversi modi di posizionare la protesi. In generale chi ha una protesi posizionata con un criterio più personalizzato riferisce di sentirla un po' meno, ma la differenza è piccola e non è certa.", "Nota rassicurante: le prove sono ancora deboli e nessun modo di posizionare la protesi è risultato nettamente migliore; la scelta spetta al chirurgo."], "kw": "protesi di ginocchio, allineamento protesi, protesi robotica, artrosi del ginocchio"}, "3": {"prof": ["Protesi totale sotto i 65 anni: lo scostamento dal neutro meccanico predice la revisione più di quello dal costituzionale", "Coorte retrospettiva bayesiana (J Arthroplasty, 2026; 470 protesi, 26 revisioni asettiche; solo abstract): errore di restaurazione HR 1,00 per grado (intervallo credibile 0,90-1,10); errore di neutralizzazione HR 1,08 per grado (0,93-1,22; probabilità di danno 87%). Nessun legame con l'Oxford Knee Score a sei mesi.", "Nota critica: 26 eventi, stima imprecisa, dipendente dai priori; nessun esito funzionale oltre sei mesi; sistema non riportato."], "mix": ["Protesi di ginocchio nei più giovani: conta la precisione sul bersaglio scelto più dell'etichetta", "In 470 protesi di ginocchio in persone sotto i 65 anni, chi aveva un asse finale più lontano dal riferimento meccanico classico tendeva ad avere più revisioni, mentre la distanza dall'asse naturale del paziente non mostrava un legame. Il posizionamento personalizzato non ha mostrato un prezzo in termini di durata a medio termine.", "Nota sul limite: le revisioni sono state 26, quindi la stima è molto incerta e lo studio guarda indietro nel tempo."], "paz": ["Protesi di ginocchio nei giovani: essere precisi nel posizionamento sembra contare", "In uno studio su 470 protesi di ginocchio in persone sotto i 65 anni, le protesi posizionate più lontano dall'asse di riferimento tendevano a essere sostituite più spesso. Il posizionamento personalizzato non ha mostrato svantaggi nei primi anni.", "Nota rassicurante: i casi di sostituzione erano pochi e lo studio non permette conclusioni sicure; ogni caso va discusso con il proprio chirurgo."], "kw": "protesi di ginocchio, protesi giovani, revisione protesi, allineamento"}, "4": {"prof": ["Osteotomia femorale distale di chiusura mediale: taglio biplanare e fratture della cerniera laterale", "Coorte retrospettiva (KSSTA, 2026; 86 ginocchia con valgo, livello III; solo abstract): HKA 180,1° ± 2,5° contro 179,8° ± 4,4° (p = 0,502), fratture della cerniera 75,0% contro 19,0% (p < 0,001) con monoplanare contro biplanare. Non inferiorità radiografica dimostrata; PROMs oltre la soglia minima in entrambi.", "Nota critica: non randomizzato, periodo dei gruppi non riportato, definizione della frattura non riportata, differenze sui PROMs non significative."], "mix": ["Correzione del ginocchio a X: un taglio su due piani sembra ridurre le fratture della cerniera", "In uno studio su 86 ginocchia con asse a X operate con un'osteotomia del femore, il taglio eseguito su due piani ha dato la stessa correzione del taglio su un piano solo, con molte meno fratture nel punto di appoggio dell'osso. Il miglioramento dei punteggi riferiti dai pazienti è stato simile nei due gruppi.", "Nota sul limite: i pazienti non sono stati assegnati a caso e lo studio guarda indietro nel tempo; il vantaggio riguarda la frattura, non i sintomi."], "paz": ["Ginocchio a X: l'intervento di correzione si può eseguire con meno complicanze dell'osso", "In uno studio su 86 ginocchia con asse a X operate con una correzione dell'osso del femore, il taglio eseguito su due piani ha avuto meno fratture nel punto di appoggio rispetto al taglio su un piano solo. La correzione ottenuta era la stessa e i pazienti sono migliorati in entrambi i gruppi.", "Nota rassicurante: lo studio guarda indietro nel tempo e non dice che una tecnica sia sempre migliore; la scelta dipende dal caso e dal chirurgo."], "kw": "ginocchio valgo, osteotomia del femore, ginocchio a X, correzione dell'asse"}, "5": {"prof": ["Protesi totale robotica con crociato posteriore conservato: fattori della lesione dell'inserzione tibiale", "Coorte prospettica (J Arthroplasty, 2026; 243 protesi robotiche; solo abstract): lesione dell'inserzione tibiale del crociato posteriore nel 10,7%. OR per qualità ossea peggiore 30,0 (IC 95% 2,5-360), artrosi mediale 2,8 (1,2-6,5), taglio mediale più spesso 2,2 (1,4-3,5), artrosi laterale 2,0 (1,4-2,9), statura 0,9 (0,8-1,0).", "Nota critica: esito intraoperatorio senza dati funzionali; stima imprecisa; sistema robotico non nominato; 26 eventi, sei variabili."], "mix": ["Protesi di ginocchio robotica: in una protesi su dieci si lede un punto di attacco del crociato posteriore", "In 243 protesi eseguite con il robot, conservando il crociato posteriore, in circa un caso su dieci il punto in cui il legamento si attacca alla tibia è risultato compromesso durante l'intervento. Più a rischio osso di qualità scadente, artrosi avanzata, taglio tibiale mediale più spesso e pazienti di statura minore.", "Nota sul limite: si guarda solo l'esito durante l'intervento e non la funzione dopo; il dato sull'osso è molto impreciso."], "paz": ["Protesi di ginocchio con robot: l'attenzione al legamento crociato posteriore", "In uno studio su 243 protesi eseguite con il robot, in circa un caso su dieci il punto in cui un legamento interno si attacca all'osso è stato intaccato durante l'intervento. Succede di più con osso più fragile, artrosi avanzata e persone più basse.", "Nota rassicurante: lo studio non dice che questo abbia conseguenze sul risultato; il chirurgo valuta queste condizioni prima dell'intervento."], "kw": "protesi di ginocchio robotica, legamento crociato posteriore, chirurgia robotica, protesi totale"}, "6": {"prof": ["Artrosi del ginocchio: frazione stromale vascolare autologa contro placebo a 12 mesi, RCT multicentrico", "RCT controllato con placebo (Am J Sports Med, 2026; 114 randomizzati, 12 mesi; solo abstract): responder 51,8% (43/83) contro 29% (9/31); differenza 22,8 punti (IC 95% 3,5-42; p a una coda 0,0149). Nessun evento avverso grave correlato al dispositivo.", "Nota critica: 31 pazienti nel placebo, intervallo largo, p a una coda, esito composito di entrambe le ginocchia, un solo anno."], "mix": ["Artrosi del ginocchio: un'iniezione di cellule del proprio grasso supera il placebo a un anno, ma con margine incerto", "In uno studio con 114 persone con artrosi del ginocchio, a una parte è stata iniettata una preparazione di cellule ricavate dal proprio grasso e ad altri un placebo. A un anno circa metà del primo gruppo ha avuto un miglioramento rilevante di dolore e funzione contro meno di un terzo del secondo.", "Nota sul limite: i partecipanti con placebo erano 31 e il margine della differenza è molto ampio; non sappiamo che cosa succeda dopo il primo anno."], "paz": ["Artrosi del ginocchio: uno studio su un'iniezione di cellule del proprio grasso", "In uno studio su 114 persone con artrosi del ginocchio, chi ha ricevuto un'iniezione di cellule ricavate dal proprio grasso ha riferito un miglioramento più spesso di chi ha ricevuto un placebo: circa metà contro meno di un terzo, dopo un anno. Non sono stati riportati eventi avversi gravi legati al trattamento.", "Nota rassicurante: lo studio è piccolo e la differenza tra i gruppi è incerta; non è un'indicazione e va discusso con il proprio medico."], "kw": "artrosi del ginocchio, infiltrazione, cellule staminali, dolore al ginocchio"}};

var ARTICLES=[{n:1,mono:'m-gray',dot:'orange',sec:'res',j:'Arthroscopy',h:'Centralizzazione del menisco con lesione di radice o allotrapianto: il consensus di esperti la considera con estrusione oltre 3 mm',v:'Consensus Delphi in tre round (22 esperti internazionali, partecipazione del 100%, livello V): 35 affermazioni mantenute su 39. Per la riparazione della radice e per il trapianto di menisco il pannello considera la centralizzazione per ridurre l\'estrusione; la indica con estrusione alla RM oltre 3 mm nella radice posteriore mediale, la sconsiglia nell\'artrosi avanzata e la sostiene con l\'osteotomia tibiale alta nel varo. Nessun tipo di fissazione è preferito.',ax:'Chahla, Dzidzishvili, Krych, LaPrade, Tapasvi e il pannello',date:'nov 2026',meta:'consensus Delphi di esperti, 22 esperti, livello V, solo abstract',pmid:'42989778',doi:'10.1002/arj.70659',journal:'Arthroscopy',authors:'Chahla J, Dzidzishvili L, Krych AJ, LaPrade RF, Tapasvi S (elenco parziale come in PubMed)',design:'Un gruppo di lavoro ha ricavato 39 affermazioni dalla letteratura pubblicata e le ha sottoposte a un processo Delphi modificato in tre round. Ventidue esperti internazionali le hanno votate su scala Likert a 5 punti; soglie di mantenimento: accordo almeno 75% e disaccordo sotto 20%. Livello V, opinione di esperti. Solo abstract: composizione completa del pannello, percentuali per affermazione e gradazione delle prove non riportate.',pop:'Non applicabile (consensus). Pannello di 22 esperti internazionali, partecipazione del 100% in tutti i round. Ambito: lesioni di radice meniscale e trapianto di menisco.',results:'Mantenute 35 affermazioni su 39. Accordo: la centralizzazione può essere considerata con la riparazione della radice e con il trapianto per ridurre l\'estrusione, migliorare la meccanica di contatto, forse favorire la guarigione della radice e limitare lo spostamento della sutura. Soglie: centralizzazione mediale da considerare con estrusione alla RM oltre 3 mm; laterale nelle lesioni di radice con lesione del legamento menisco-femorale ed estrusione oltre 3 mm. Non raccomandata nell\'artrosi avanzata; sostenuta insieme all\'osteotomia tibiale alta nel varo con estrusione mediale sintomatica. Transtibiale, ancore e costrutti ibridi sono accettabili se la fissazione è individualizzata e senza sovra-tensione. Percentuali di accordo per singola affermazione: non riportate nell\'abstract.',concl:'Gli autori: considerare la centralizzazione con estrusione oltre 3 mm nella radice posteriore mediale e in lesioni laterali selezionate; sconsigliarla nell\'artrosi avanzata; nessun costrutto di fissazione preferito; servono studi a lungo termine per confermare durata e protezione articolare.',limits:'Opinione di esperti (livello V), non una prova: nasce dalla stessa letteratura prevalentemente osservazionale · Percentuali di accordo per affermazione, composizione completa del pannello e dichiarazioni di conflitto di interesse non sono nell\'abstract · La soglia di 3 mm è del pannello, non è stata validata in un confronto con la sola sutura · «Può essere considerata» non è un\'indicazione',perte:'Arancione: rifissi la radice mediale con tecnica transtibiale pull-out e, per quanto risulta dal tuo profilo, senza centralizzazione; è il caso in cui il pannello, con estrusione oltre 3 mm, suggerisce di valutarne l\'aggiunta. Non dice che la transtibiale sia inferiore: la dichiara accettabile. Vale come cornice, non come prova: la meta-analisi del 27 agosto non aveva trovato beneficio clinico dalla centralizzazione (differenza media di estrusione 0,4 mm; IC 95% da -0,34 a 1,22; I² 89%). Cosa fare: misura e referta l\'estrusione alla RM prima della rifissazione; se supera 3 mm, tieni la centralizzazione come opzione da discutere, dichiarando che il fondamento è un consensus. Nessun cambio di indicazione per questo documento da solo.'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'J Arthroplasty',h:'Protesi totale: allineamento funzionale e cinematico migliorano il Forgotten Joint Score rispetto al meccanico, ma la certezza è bassa',v:'Revisione sistematica con meta-analisi di rete (61 studi, 22 RCT e 39 osservazionali, 7.822 pazienti). Rispetto all\'allineamento meccanico il Forgotten Joint Score migliora con il funzionale (differenza media 14,24; IC 95% 3,32-25,16), il cinematico non restrittivo (12,28; IC 95% 9,06-15,51) e il cinematico restrittivo (8,75; IC 95% 3,41-14,08). Solo il funzionale supera la soglia minima rilevante, con eterogeneità alta; la certezza GRADE è bassa o molto bassa.',ax:'Tan, Lim, Thorpe, Kon Kam King, Moo',date:'nov 2026',meta:'meta-analisi di rete, 61 studi (22 RCT), 7.822 pazienti, solo abstract',pmid:'42994644',doi:'10.1016/j.arth.2026.11.002',journal:'The Journal of arthroplasty',authors:'Tan GHC, Lim HA, Thorpe LR, Kon Kam King C, Moo IH',design:'Revisione sistematica con meta-analisi a coppie e meta-analisi di rete frequentista (Changi General Hospital e Università nazionale di Singapore). Quattro banche dati, da gennaio 2000 a febbraio 2026; RCT e studi comparativi osservazionali su protesi totale primaria. Esito primario: Forgotten Joint Score. Secondari: Oxford Knee Score, WOMAC, mobilità. Certezza con GRADE. Solo abstract.',pop:'61 studi (22 RCT, 39 osservazionali), 7.822 pazienti con protesi totale primaria. Sistemi di navigazione o robot, tipo di impianto e follow-up: non riportati nell\'abstract.',results:'Forgotten Joint Score rispetto all\'allineamento meccanico: funzionale differenza media 14,24 (IC 95% 3,32-25,16), cinematico non restrittivo 12,28 (IC 95% 9,06-15,51), cinematico restrittivo 8,75 (IC 95% 3,41-14,08). Solo il funzionale supera la soglia minima rilevante inferiore; eterogeneità alta. Il vantaggio del cinematico non restrittivo è 13,76 negli osservazionali contro 7,49 negli RCT. Oxford Knee Score, WOMAC e mobilità: effetti più piccoli e in genere sotto le soglie rilevanti. Certezza GRADE bassa per il cinematico restrittivo contro meccanico, molto bassa per gli altri confronti principali; nella graduatoria dei soli RCT l\'ordine è meno netto.',concl:'Gli autori: le strategie non meccaniche migliorano il Forgotten Joint Score in modo statisticamente significativo, ma una superiorità clinicamente rilevante e certa rispetto al meccanico non è dimostrata; servono RCT più lunghi e adeguatamente dimensionati prima di preferire una strategia.',limits:'Quasi due terzi degli studi sono osservazionali, e il vantaggio si riduce negli RCT · Eterogeneità alta, certezza bassa o molto bassa · I confronti diretti fra strategie sono scarsi: la graduatoria di rete poggia su confronti indiretti · L\'abstract non separa i sistemi robotici né dice come fosse definito l\'allineamento funzionale · Un solo punteggio come esito primario',perte:'Verde: l\'allineamento è la scelta di pianificazione che fai con il robot nella protesi totale. Il messaggio utile è la distanza fra statistica e clinica: la direzione favorisce il funzionale e il cinematico, ma solo il funzionale supera la soglia minima rilevante e la certezza è bassa. L\'abstract non dice quale sistema robotico, quindi non è trasferibile al VELYS senza riserve. Cosa fare: nessun cambio; se spieghi la scelta del bersaglio di allineamento a un paziente, dichiara che il vantaggio sul meccanico è plausibile ma non certo. Nella stessa giornata un lavoro su 470 protesi (scheda 3) legge la questione dal lato della precisione.'},
{n:3,mono:'m-gray',dot:'green',sec:'res',j:'J Arthroplasty',h:'Protesi totale sotto i 65 anni: lo scostamento dal neutro meccanico predice la revisione più dello scostamento dall\'allineamento costituzionale',v:'Coorte retrospettiva con analisi bayesiana a rischi competitivi (Whangārei, Nuova Zelanda): 470 protesi in 376 pazienti sotto i 65 anni, 26 revisioni asettiche. L\'errore di restaurazione dell\'allineamento costituzionale non è informativo (HR 1,00 per grado; intervallo credibile 95% 0,90-1,10); l\'errore di neutralizzazione verso il neutro meccanico è probabilmente dannoso (HR 1,08 per grado; intervallo credibile 0,93-1,22; probabilità di danno 87%).',ax:'Hoskins, Gusho, Rosser, Lim, Dunstall',date:'nov 2026',meta:'coorte retrospettiva, 470 protesi, 26 revisioni asettiche, solo abstract',pmid:'42994637',doi:'10.1016/j.arth.2026.11.026',journal:'The Journal of arthroplasty',authors:'Hoskins W, Gusho C, Rosser K, Lim M, Dunstall K',design:'Analisi retrospettiva di protesi totali in pazienti sotto i 65 anni con radiografie a lunga lastra pre e postoperatorie e follow-up minimo di due anni. Due esposizioni per grado: errore di restaurazione (variazione assoluta dell\'angolo anca-ginocchio-caviglia aritmetico) ed errore di neutralizzazione (scostamento da 180° postoperatorio). Esito primario: revisione asettica, con morte e infezione come eventi competitivi. Modello bayesiano preregistrato con priori debolmente informativi e scettici. Solo abstract.',pop:'470 protesi totali in 376 pazienti sotto i 65 anni, 26 revisioni asettiche. Tipo di impianto, sistema di navigazione o robot, definizione di allineamento costituzionale operativa: non riportati nell\'abstract.',results:'Errore di restaurazione: HR 1,00 per grado (intervallo credibile 95% 0,90-1,10; probabilità di danno qualsiasi 52%). Errore di neutralizzazione: HR 1,08 per grado (intervallo credibile 0,93-1,22; probabilità di danno 87%; probabilità di un effetto clinicamente rilevante, almeno 1,5 volte su 5°, 50%). Probabilità che la neutralizzazione conti più della restaurazione: 81%, stabile con il priore scettico. Modelli di Cox e Fine-Gray concordi. Nessuna delle due associata all\'Oxford Knee Score a sei mesi.',concl:'Gli autori: nei pazienti giovani lo scostamento dal neutro meccanico predice la revisione asettica più di quello dall\'allineamento costituzionale; l\'allineamento personalizzato non mostra penalità di sopravvivenza a medio termine; conta più la precisione sul bersaglio scelto che l\'etichetta.',limits:'Retrospettivo, 26 eventi: gli intervalli includono l\'assenza di effetto e un aumento sostanziale · Probabilità bayesiane dipendono dai priori · Il neutro meccanico è anche un riferimento che molti allineamenti personalizzati sfiorano per costruzione: l\'esposizione è definita dal bersaglio, non dal modo in cui si è operato · Nessun esito funzionale oltre i sei mesi',perte:'Verde: stessa domanda della scheda 2, letta dal lato della precisione, con un esito duro (la revisione). Il dato non dice che un bersaglio sia migliore: dice che nello studio la distanza dal bersaglio dichiarato pesava più della scelta del bersaglio, e che l\'allineamento personalizzato non ha mostrato un prezzo a medio termine. Con 26 revisioni resta una stima molto incerta. Cosa fare: nessun cambio; se usi il robot per l\'allineamento funzionale, registra la distanza fra piano e risultato postoperatorio, perché è il parametro che qui si associa alla revisione.'},
{n:4,mono:'m-gray',dot:'green',sec:'res',j:'KSSTA',h:'Osteotomia femorale distale di chiusura mediale: il taglio biplanare ha un quarto delle fratture della cerniera laterale, con la stessa correzione',v:'Coorte retrospettiva consecutiva (ASST Pini-CTO, Milano; livello III): 82 pazienti, 86 ginocchia con valgo, taglio monoplanare (44) contro biplanare (42). Correzione equivalente (HKA 180,1° ± 2,5° contro 179,8° ± 4,4°; p = 0,502). Fratture della cerniera laterale 75,0% contro 19,0% (p < 0,001); non inferiorità del biplanare dimostrata formalmente per i parametri radiografici. I PROMs migliorano oltre la soglia minima in entrambi i gruppi.',ax:'Maione, Pozzi, Gallizzi, Parmigiani, Romano, Menon, Calanna, Compagnoni, Ferrua, Berruto, Randelli',date:'nov 2026',meta:'coorte retrospettiva consecutiva, 86 ginocchia, livello III, solo abstract',pmid:'42994401',doi:'10.1002/ksa.70673',journal:'Knee surgery, sports traumatology, arthroscopy',authors:'Maione A, Pozzi P, Gallizzi S, Parmigiani MD, Romano S, Menon A, Calanna F, Compagnoni R, Ferrua P, Berruto M, Randelli PS',design:'Analisi retrospettiva di una serie consecutiva di osteotomie femorali distali di chiusura mediale per valgo, 2010-2024, due centri della rete Pini-CTO di Milano. Taglio monoplanare contro biplanare. Esito primario radiografico (HKA e angolo femorale distale laterale su lastre a lunga lastra in carico); secondari: fratture della cerniera, complicanze, IKDC, Knee Society Score, KOOS, Tegner, VAS. Livello III dichiarato (caso-controllo). Solo abstract.',pop:'82 pazienti (86 ginocchia) con valgo, 2010-2024: 44 ginocchia monoplanari, 42 biplanari. Età, sesso, fissazione, follow-up e se i due gruppi appartengano a periodi diversi: non riportati nell\'abstract.',results:'HKA postoperatorio 180,1° ± 2,5° contro 179,8° ± 4,4° (p = 0,502); angolo femorale distale laterale 90,7° ± 2,6° contro 91,5° ± 4,1° (p = 0,339); non inferiorità formale per tutti i parametri radiografici. Fratture della cerniera 75,0% contro 19,0% (p < 0,001); dai conteggi derivati dalle percentuali (33/44 contro 8/42, calcolo mio) rischio relativo 3,94 (IC 95% 2,06-7,52). Tutti i PROMs migliorano oltre la soglia minima rilevante; le tendenze a favore del biplanare su attività e dolore non sono significative.',concl:'Gli autori: il protocollo biplanare si associa a meno fratture della cerniera laterale con correzione coronale comparabile; le tendenze su attività e dolore sono ipotesi; giustificato uno studio prospettico.',limits:'Retrospettivo, non randomizzato: il taglio può coincidere con un\'epoca o con una curva di apprendimento (mio rilievo, il periodo dei due gruppi non è riportato) · Non è dichiarato come si definisse e si cercasse la frattura della cerniera; una quota del 75% è insolitamente alta e invita a leggere il testo · PROMs senza differenze fra gruppi: il beneficio è radiografico e di complicanza, non clinico · Solo valgo, solo chiusura mediale',perte:'Verde: osteotomia correttiva, un tuo campo, e la complicanza della cerniera è la ragione per cui questo taglio si discute. Dà un numero chiaro (RR 3,94 per il monoplanare) ma in un confronto non randomizzato e con una frequenza di fratture molto alta rispetto a ciò che si legge di solito: prima di cambiare tecnica servono la definizione di frattura e il periodo dei due gruppi, che stanno nel testo completo (non letto). Cosa fare: se esegui chiusure mediali femorali, nota nei tuoi casi la frequenza di fratture della cerniera e il piano di taglio; non è un argomento per cambiare da solo.'},
{n:5,mono:'m-gray',dot:'green',sec:'res',j:'J Arthroplasty',h:'Protesi totale robotica con conservazione del crociato posteriore: il 10,7% ha una lesione dell\'inserzione tibiale, più probabile con osso scadente e tagli mediali spessi',v:'Coorte prospettica consecutiva (Sydney Knee Specialists): 243 protesi robotiche a conservazione del crociato posteriore, 26 (10,7%) con inserzione tibiale compromessa all\'impianto. Predittori indipendenti: qualità ossea peggiore (OR 30,0; IC 95% 2,5-360), artrosi mediale (OR 2,8; IC 95% 1,2-6,5) e laterale (OR 2,0; IC 95% 1,4-2,9) più gravi, taglio tibiale mediale più spesso (OR 2,2; IC 95% 1,4-3,5), statura minore (OR 0,9 per unità; IC 95% 0,8-1,0).',ax:'Leggieri, Wood, Sergis, Wernecke, Chen, MacDessi',date:'nov 2026',meta:'coorte prospettica consecutiva, 243 protesi robotiche, solo abstract',pmid:'42994647',doi:'10.1016/j.arth.2026.11.012',journal:'The Journal of arthroplasty',authors:'Leggieri F, Wood JA, Sergis N, Wernecke GC, Chen DB, MacDessi SJ',design:'Studio prospettico su 243 protesi totali robotiche a conservazione del crociato posteriore consecutive, gennaio-agosto 2025. Stato dell\'inserzione tibiale del crociato posteriore (intatta o compromessa) valutato all\'impianto; raccolti dati demografici, allineamento preoperatorio, grado di artrosi ICRS, qualità ossea (scala a 5 punti) e spessore del taglio tibiale. Regressione logistica multivariata. Solo abstract; sistema robotico, impianto e follow-up non riportati.',pop:'243 protesi robotiche consecutive a conservazione del crociato posteriore, gennaio-agosto 2025; 26 con lesione dell\'inserzione (10,7%). Età, sesso e sistema robotico non riportati nell\'abstract.',results:'Lesione dell\'inserzione tibiale nel 10,7% (26 su 243). Predittori indipendenti (p globale 0,014): qualità ossea peggiore OR 30,0 (IC 95% 2,5-360; p = 0,012), artrosi mediale più grave OR 2,8 (IC 95% 1,2-6,5), taglio tibiale mediale più spesso OR 2,2 (IC 95% 1,4-3,5; p = 0,010), artrosi laterale più grave OR 2,0 (IC 95% 1,4-2,9; p = 0,005), statura OR 0,9 (IC 95% 0,8-1,0; p = 0,023); interazione statura × qualità ossea p = 0,007. Taglio mediale 6,1 ± 1,3 mm contro 6,9 ± 0,9 mm (p = 0,001).',concl:'Gli autori: statura minore, osso scadente e artrosi avanzata aumentano il rischio di lesione dell\'inserzione del crociato posteriore anche con la protezione haptica del robot; servono strategie di prevenzione.',limits:'Esito intraoperatorio: nessun dato su stabilità, funzione o sopravvivenza · L\'intervallo dell\'OR per la qualità ossea (2,5-360) rende la stima molto imprecisa · 26 eventi e sei variabili: rischio di sovradattamento · Sistema robotico non nominato, soglie di compromissione non definite nell\'abstract · Un solo centro, otto mesi',perte:'Verde: protesi totale robotica, il tuo ambito, con la conservazione del crociato come punto che il robot da solo non risolve. Il dato pratico è che la protezione haptica non azzera il rischio e che i fattori sono riconoscibili prima di tagliare: osso scadente, artrosi avanzata, taglio mediale spesso, statura bassa. Non è detto che il sistema sia il VELYS. Cosa fare: se usi impianti a conservazione del crociato, valuta la qualità ossea e lo spessore del taglio mediale nella pianificazione; nessun cambio di indicazione per un esito intraoperatorio.'},
{n:6,mono:'m-gray',dot:'gray',sec:'res',j:'Am J Sports Med',h:'Frazione stromale vascolare autologa nell\'artrosi del ginocchio: un\'iniezione supera il placebo a 12 mesi, con differenza imprecisa',v:'RCT multicentrico controllato con placebo (livello 1 dichiarato): 114 randomizzati (83 frazione stromale, 31 placebo) con artrosi moderata-grave. Responder a 12 mesi 51,8% (43/83) contro 29% (9/31); differenza 22,8 punti (IC 95% 3,5-42); p a una coda 0,0149. Nessun evento avverso grave correlato al dispositivo.',ax:'Garza, Moorman, Baria, Santa Maria, Bowen, Sparks, Rubin',date:'nov 2026',meta:'RCT multicentrico controllato con placebo, 114 pazienti, 12 mesi, solo abstract',pmid:'42989897',doi:'10.1177/03635465261498163',journal:'The American journal of sports medicine',authors:'Garza JR, Moorman CT, Baria M, Santa Maria D, Bowen J, Sparks N, Rubin JP',design:'RCT multicentrico, controllato con placebo (livello di evidenza 1; IDE 16734, NCT04440189). Adulti di 35-85 anni con artrosi sintomatica (WOMAC dolore almeno 8, Outerbridge 2-4 alla RM, Kellgren-Lawrence 2-4); frazione stromale vascolare adiposa autologa preparata con sistema al letto del paziente, 25 milioni di cellule, una iniezione intra-articolare. Esito primario composito di responder a 12 mesi (dolore e funzione, ginocchio indice e controlaterale). Solo abstract; cecità, sponsor e conflitti di interesse non riportati.',pop:'618 valutati, 114 randomizzati: 83 frazione stromale e 31 placebo (rapporto 2,7 a 1). Età media, sesso e BMI: non riportati nell\'abstract.',results:'Responder a 12 mesi 51,8% (43/83) contro 29% (9/31): differenza 22,8 punti (IC 95% 3,5-42; p a una coda 0,0149). Calcolo mio dai conteggi: rischio relativo 1,78 (IC 95% 0,99-3,21). Nessun evento avverso grave correlato al dispositivo. Risonanza a 12 mesi raccolta, esito non riportato nell\'abstract.',concl:'Gli autori: una iniezione di 25 milioni di cellule dà miglioramenti di dolore e funzione statisticamente superiori e clinicamente rilevanti rispetto al placebo a 12 mesi, senza eventi avversi gravi correlati al dispositivo.',limits:'Soli 31 pazienti nel braccio placebo; intervallo molto largo (da 3,5 a 42 punti) · Il p è a una coda, un criterio più indulgente: con il calcolo mio a due code l\'intervallo del rischio relativo tocca 1 · Responder composito di dolore e funzione di entrambe le ginocchia: nessun risultato su ciascuna componente nell\'abstract · Un solo anno · Sponsor e cecità non nell\'abstract',perte:'Grigio: infiltrazioni biologiche, fuori dalle tue tecniche, ma è un RCT con placebo su una terapia di cui i pazienti chiedono. Il dato utile: effetto plausibile e ancora imprecisa la sua entità; nessuna informazione su durata oltre un anno né su effetti strutturali. Cosa fare: nessun cambio; se un paziente lo chiede, la risposta onesta è che un RCT di 114 persone mostra un vantaggio a 12 mesi con intervallo largo e p a una coda.'}];

var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Sabato sette novembre, sei lavori, nessuna scheda rossa. Nessun richiamo di dispositivi nuovo e nessuna ritrattazione che ti riguardi; il raccoglitore è quello di ieri mattina, tutte le fonti hanno risposto e nessun citante nuovo tocca i tuoi verdetti passati. Il lavoro del giorno è un consensus: ventidue esperti internazionali, in tre round, hanno scritto quando considerare la centralizzazione del menisco con la riparazione della radice e con il trapianto. La soglia è un'estrusione alla risonanza oltre tre millimetri nella radice posteriore mediale; la sconsigliano nell'artrosi avanzata, la sostengono con l'osteotomia tibiale alta nel varo, e giudicano accettabili tunnel transtibiali, ancore e costrutti ibridi. È opinione di esperti, livello cinque: la meta-analisi di agosto non aveva trovato un beneficio clinico dalla centralizzazione. Tocca la tua rifissazione transtibiale e muove la tensione sulla radice meniscale, ma non cambia ancora l'indicazione. Poi due lavori sull'allineamento della protesi totale. La meta-analisi di rete su sessantuno studi dice che l'allineamento funzionale e il cinematico migliorano il Forgotten Joint Score rispetto al meccanico, ma solo il funzionale supera la soglia rilevante e la certezza è bassa. La coorte bayesiana su quattrocentosettanta protesi sotto i sessantacinque anni legge la stessa domanda dal lato della revisione: conta più la distanza dal bersaglio che il bersaglio, con ventisei eventi e una stima molto incerta. Quarta scheda, osteotomia femorale distale di chiusura mediale: il taglio biplanare ha molte meno fratture della cerniera con la stessa correzione, ma lo studio è retrospettivo e non randomizzato. Quinta, protesi robotica con crociato posteriore conservato: in una su dieci l'inserzione tibiale risulta compromessa, più spesso con osso scadente e tagli mediali spessi. In coda, un RCT sulla frazione stromale vascolare autologa nell'artrosi: vantaggio a dodici mesi con intervallo largo e p a una coda. Dodici brevi e tre scoperte nella seconda pagina.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Sabato sette novembre, sei lavori, nessuna scheda rossa. Nessun richiamo nuovo, nessuna ritrattazione che ti riguardi e nessun citante nuovo sui tuoi verdetti passati."}, {"chi": "B", "t": "Il lavoro del giorno?"}, {"chi": "A", "t": "Un consensus Delphi di ventidue esperti internazionali sulla centralizzazione del menisco con la riparazione della radice e il trapianto. La considerano con estrusione alla risonanza oltre tre millimetri nella radice posteriore mediale."}, {"chi": "B", "t": "Quindi per la mia transtibiale pull-out?"}, {"chi": "A", "t": "La dichiarano accettabile, insieme alle ancore e ai costrutti ibridi. Ma con estrusione oltre i tre millimetri suggeriscono di valutare l'aggiunta. Sconsigliata nell'artrosi avanzata, sostenuta con l'osteotomia tibiale alta nel varo."}, {"chi": "B", "t": "È una prova?"}, {"chi": "A", "t": "No, è opinione di esperti, livello cinque. La meta-analisi di agosto non aveva trovato beneficio clinico. Muove la tensione sulla radice, non l'indicazione."}, {"chi": "B", "t": "Poi?"}, {"chi": "A", "t": "Due lavori sull'allineamento della protesi totale. La meta-analisi di rete su sessantuno studi dice che funzionale e cinematico migliorano il Forgotten Joint Score rispetto al meccanico, ma solo il funzionale supera la soglia rilevante, e la certezza è bassa."}, {"chi": "B", "t": "E l'altro?"}, {"chi": "A", "t": "Una coorte bayesiana su quattrocentosettanta protesi sotto i sessantacinque anni: conta più la distanza dal bersaglio che il bersaglio scelto. Ventisei revisioni, stima molto incerta."}, {"chi": "B", "t": "Osteotomia?"}, {"chi": "A", "t": "Femorale distale di chiusura mediale: il taglio biplanare ha molte meno fratture della cerniera, stessa correzione. Retrospettivo, non randomizzato, quindi da leggere con prudenza."}, {"chi": "B", "t": "E per la protesi robotica?"}, {"chi": "A", "t": "Con il crociato posteriore conservato, in una su dieci l'inserzione tibiale risulta compromessa, più spesso con osso scadente e tagli mediali spessi. Poi, in coda, un RCT sulla frazione stromale autologa nell'artrosi: vantaggio a dodici mesi con intervallo largo."}];

